import {fa,escapeHTML as esc,total} from './core.mjs?v=1';
export const roles={
 alireza:{name:'علیرضا',title:'مدیرعامل',kind:'manager',hr:true},
 behnam:{name:'بهنام',title:'مدیر کارخانه',kind:'manager',hr:true},
 haji:{name:'حاجی',title:'مدیریت عملیات',kind:'manager',hr:false},
 nazanin:{name:'نازنین',title:'مالی و حسابداری',kind:'finance',hr:false},
 employee:{name:'سایر کارکنان',title:'همکار تولید',kind:'employee',hr:false},
};
export const inventory=[{metal:'نقره',total:28000,reserved:7000,available:21000},{metal:'طلا',total:1200,reserved:300,available:900}];
export const initialFinance=[
 {id:'pay-1',name:'همکار نمونه ۱',title:'دستور پرداخت پرسنلی',amount:360000000,category:'personnel',status:'pending',due:'امروز'},
 {id:'pay-2',name:'تأمین‌کننده نمونه',title:'خرید اقلام مصرفی',amount:48000000,category:'purchase',status:'pending',due:'امروز'},
 {id:'pay-3',name:'همکار نمونه ۲',title:'دستور پرداخت پرسنلی',amount:18000000,category:'personnel',status:'pending',due:'فردا'},
 {id:'pay-4',name:'خرید کارگاه',title:'هزینه ابزار',amount:12000000,category:'expense',status:'recorded',due:'دیروز'},
 {id:'pay-5',name:'تنخواه عملیاتی',title:'شارژ تنخواه تأییدشده',amount:60000000,category:'cash',status:'pending',due:'فردا'},
];
export const financeLabel=r=>r.status==='pending'?'در انتظار اقدام':r.status==='recorded'?'هزینه ثبت‌شده':'فیش ثبت‌شده';
export function taskTable(tasks,icon){return `<div class="enterprise-table-wrap"><table class="enterprise-table"><thead><tr><th>تسک</th><th>نوع</th><th>مرحله / محل</th><th>مسئول</th><th>وضعیت</th><th>موعد</th><th></th></tr></thead><tbody>${tasks.map(t=>`<tr><td><button class="table-task" data-action="open-task" data-id="${esc(t.id)}"><img src="${esc(t.cover)}" alt=""><span><b>${esc(t.title)}</b><small class="ltr">${esc(t.code)}</small></span></button></td><td>${t.type==='production'?'محصول':'عمومی'}</td><td>${esc(t.location)}</td><td>${esc(t.owner)}</td><td><span class="pill ${t.status==='waiting'?'waiting':'active'}">${({requested:'منتظر تأیید',waiting:'در انتظار',active:'در جریان',done:'به اتمام رسیده',cancelled:'لغوشده'}[t.status]||'در انتظار')}</span></td><td>${esc(t.due||'بدون موعد')}</td><td><button class="icon-btn" data-action="open-task" data-id="${esc(t.id)}" aria-label="جزئیات ${esc(t.title)}">${icon('chevronLeft','sm')}</button></td></tr>`).join('')}</tbody></table></div>`;}
export function managementDashboard({tasks,role,icon}){const active=tasks.filter(t=>!['done','cancelled'].includes(t.status)),waiting=active.filter(t=>['waiting','requested'].includes(t.status));const stages=[['آماده‌سازی',active.filter(t=>t.type==='general'&&t.status==='active').length],['تولید',active.filter(t=>t.type==='production'&&t.status==='active').length],['در انتظار',waiting.length]];const max=Math.max(1,...stages.map(s=>s[1]));return `<section class="enterprise-dashboard"><div class="enterprise-breadcrumb">MORIYATI WORKSPACE <span>/</span> مدیریت کارخانه</div><div class="page-heading"><div><h1>داشبورد عملیات</h1><small>نمای ${esc(role.name)} · وضعیت جاری کارخانه</small></div><div class="enterprise-actions"><button class="secondary" data-action="inventory">${icon('layers','sm')}موجودی صندوق</button><button class="primary" data-action="create">${icon('plus','sm')}تسک جدید</button></div></div><div class="kpi-grid"><button class="kpi" data-action="nav" data-route="explore"><span>تسک‌های فعال ${icon('grid','sm')}</span><strong>${fa(active.length)}</strong><small>محصول و عمومی</small></button><button class="kpi" data-action="nav" data-route="activity"><span>نیازمند پیگیری ${icon('clock','sm')}</span><strong>${fa(waiting.length)}</strong><small>در انتظار یا تأیید</small></button><button class="kpi" data-action="inventory"><span>نقره در دسترس ${icon('layers','sm')}</span><strong>${fa(inventory[0].available)}<em>گرم</em></strong><small>${fa(inventory[0].reserved)} گرم رزروشده</small></button><button class="kpi" data-action="inventory"><span>طلا در دسترس ${icon('layers','sm')}</span><strong>${fa(inventory[1].available)}<em>گرم</em></strong><small>${fa(inventory[1].reserved)} گرم رزروشده</small></button></div><div class="enterprise-panels"><section class="enterprise-panel"><header><h2>توزیع کارهای جاری</h2><small>بر اساس وضعیت تسک‌ها</small></header><div class="work-distribution">${stages.map(([label,value])=>`<div><span>${label}</span><div class="distribution-track"><i style="width:${value/max*100}%"></i></div><b>${fa(value)}</b></div>`).join('')}</div></section><section class="enterprise-panel"><header><h2>اقدام بعدی</h2><button class="text-link" data-action="nav" data-route="activity">همه اعلان‌ها</button></header>${waiting.slice(0,2).map(t=>`<button class="record" data-action="open-task" data-id="${esc(t.id)}"><span class="record-icon">${icon('clock','sm')}</span><span><strong>${esc(t.title)}</strong><small>${esc(t.location)}</small></span>${icon('chevronLeft','sm')}</button>`).join('')||'<p class="muted">موردی در انتظار نیست.</p>'}</section></div><section class="enterprise-panel table-panel"><header><h2>گردش کارهای کارخانه</h2><button class="text-link" data-action="nav" data-route="explore">مشاهده همه</button></header>${taskTable(active.slice(0,6),icon)}</section><p class="enterprise-footnote">اطلاعات نمونه برای ارزیابی رابط · ${role.hr?'دید عملیات و مدیریت پرسنل طبق مجوز حساب':'دید عملیات؛ پرونده HR دیگران در این حساب نمایش داده نمی‌شود'}</p></section>`;}
export function financeDashboard({records,desktop,icon,role}){const pending=records.filter(r=>r.status==='pending');if(!desktop)return `<section class="finance-mobile"><div class="page-heading"><div><h1>میزکار مالی</h1><small>${esc(role?.name||'نازنین')} · مالی و حسابداری کارخانه</small></div></div><div class="finance-mobile-summary"><span>دستورهای در انتظار</span><strong>${fa(pending.length)}</strong><small>${fa(total(pending,'amount'))} ریال</small></div><div class="mobile-finance-actions"><button data-action="finance-list">${icon('list')}دستورها</button><button data-action="expense">${icon('plus')}ثبت هزینه</button><button data-action="finance-receipts">${icon('file')}فیش‌ها</button><button data-action="export-finance">${icon('download')}خروجی</button></div><button class="list-link" data-action="finance-accounts">${icon('wallet')}حساب‌ها و تنخواه${icon('chevronLeft')}</button><button class="list-link" data-action="finance-expenses">${icon('chart')}هزینه‌ها و اسناد${icon('chevronLeft')}</button><h2 class="notification-heading">همه دستورها و اسناد</h2>${records.map(r=>`<button class="record" data-action="finance-detail" data-id="${esc(r.id)}"><span class="record-icon">${icon('wallet')}</span><span><strong>${esc(r.name)}</strong><small>${esc(r.title)}</small><small>${financeLabel(r)}</small></span><span class="record-value">${fa(r.amount)}<small>ریال</small></span></button>`).join('')}</section>`;return `<section class="enterprise-dashboard"><div class="enterprise-breadcrumb">MORIYATI WORKSPACE <span>/</span> مالی کارخانه</div><div class="page-heading"><div><h1>میزکار مالی</h1><small>${esc(role?.name||'نازنین')} · پرداخت‌ها، اسناد و هزینه‌های کارخانه</small></div><div class="enterprise-actions"><button class="secondary" data-action="export-finance">${icon('download','sm')}خروجی فهرست</button><button class="primary" data-action="expense">${icon('plus','sm')}ثبت هزینه</button></div></div><div class="kpi-grid"><button class="kpi" data-action="finance-list"><span>در انتظار اقدام ${icon('clock','sm')}</span><strong>${fa(pending.length)}</strong><small>دستور پرداخت</small></button><button class="kpi" data-action="finance-list"><span>مبلغ دستورها ${icon('wallet','sm')}</span><strong>${fa(total(pending,'amount')/1000000)}<em>میلیون ریال</em></strong><small>پرداخت‌شده محسوب نمی‌شود</small></button><button class="kpi" data-action="finance-receipts"><span>فیش‌های ثبت‌شده ${icon('file','sm')}</span><strong>${fa(records.filter(r=>r.status==='receipt').length)}</strong><small>در همین پیش‌نمونه</small></button><button class="kpi" data-action="finance-expenses"><span>هزینه‌های ثبت‌شده ${icon('chart','sm')}</span><strong>${fa(total(records.filter(r=>r.category==='expense'),'amount')/1000000)}<em>میلیون ریال</em></strong><small>اسناد هزینه کارخانه</small></button></div><div class="enterprise-panels"><section class="enterprise-panel"><header><h2>حساب‌ها و تنخواه</h2><small>نمای نمونه</small></header><div class="record"><span class="record-icon">${icon('wallet')}</span><span><strong>حساب اصلی کارخانه</strong><small>مشاهده و ثبت سند</small></span><span class="record-value">۱</span></div><div class="record"><span class="record-icon">${icon('layers')}</span><span><strong>تنخواه عملیاتی</strong><small>خرید و تسویه اسناد</small></span><span class="pill">فعال</span></div></section><section class="enterprise-panel"><header><h2>${role?.name==='حاجی'?'اسناد هزینه کارخانه':'دستورهای پرداخت پرسنلی'}</h2><small>${role?.name==='حاجی'?'هزینه‌های عملیاتی':'نام، مبلغ، فیش'}</small></header>${pending.filter(r=>role?.name==='حاجی'?r.category!=='personnel':r.category==='personnel').map(r=>`<button class="record" data-action="finance-detail" data-id="${esc(r.id)}"><span class="record-icon">${icon('file')}</span><span><strong>${esc(r.name)}</strong><small>دستور پرداخت</small></span><span class="record-value">${fa(r.amount)}<small>ریال</small></span></button>`).join('')}</section></div><section class="enterprise-panel table-panel"><header><h2>گردش پرداخت‌ها و هزینه‌ها</h2><span class="pill">${fa(records.length)} مورد</span></header><div class="enterprise-table-wrap"><table class="enterprise-table"><thead><tr><th>نام / طرف حساب</th><th>شرح مجاز</th><th>مبلغ · ریال</th><th>وضعیت</th><th>زمان</th><th></th></tr></thead><tbody>${records.map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${esc(r.title)}</td><td class="financial-number">${fa(r.amount)}</td><td><span class="pill ${r.status==='pending'?'waiting':'active'}">${financeLabel(r)}</span></td><td>${esc(r.due||'اکنون')}</td><td><button class="secondary compact" data-action="finance-detail" data-id="${esc(r.id)}">جزئیات</button></td></tr>`).join('')}</tbody></table></div></section><p class="enterprise-footnote">اسناد و مقادیر نمونه‌اند؛ هیچ پرداخت بانکی از این صفحه انجام نمی‌شود.</p></section>`;}
